-- Sample data for the INTEGRITY (anti-cheat) REPORT: exam > Statistics > Integrity.
-- Run in the H2 console AFTER exam-statistics-sample-data.sql (it reuses exams 9001/9002 and their attempts).
-- Re-runnable: it deletes its own integrity rows first and re-applies the updates.
--
-- What you get (exam 9002 "[Stats Demo] OOP - Midterm", 45 min; exam 9001 "Quiz 1", 15 min):
--  * attempt 9111 (student 4): tab switches + copy, DUPLICATE essay answer with students 5 and 7
--  * attempt 9112 (student 5): DIFFERENT_PERSON, face missing, extra person (with evidence photos), duplicate answer
--  * attempt 9113 (student 6): fullscreen exits, right-click, shortcut, head turned, camera covered; submitted in 6 min (< 20% of 45 min -> "Submitted too fast" warning)
--  * attempt 9114 (student 7): camera off, paste, multi-session, near-duplicate answer of student 4/5
--  * attempt 9110 (student 2): only one window blur; essay #2 is DUPLICATE with student 8 (attempt 9115)
--  * attempt 9109 (exam 9001, student 9): submitted in 2 min of 15 (< 20%) -> "Submitted too fast" warning only
--  * attempt 9105 (exam 9001, student 5): tab switches / window blurs
--  * entry photos for attempts 9110-9115

DELETE FROM EXAM_PROCTOR_IMAGE WHERE EXAM_ID IN (9001, 9002);
DELETE FROM EXAM_INTEGRITY_EVENT WHERE EXAM_ID IN (9001, 9002);

UPDATE EXAM SET ANTI_CHEAT_ENABLED = TRUE, DETECT_TAB_SWITCH = TRUE, BLOCK_COPY_PASTE = TRUE,
       REQUIRE_FULLSCREEN = TRUE, SINGLE_SESSION = TRUE, CAMERA_PROCTORING = TRUE, NOTIFY_ON_VIOLATION = TRUE
 WHERE ID IN (9001, 9002);

-- Make the two essay questions of the midterm the SAME source question for every student,
-- so the similarity check can compare their answers.
UPDATE EXAM_ATTEMPT_QUESTION SET SOURCE_QUESTION_ID = 9250 WHERE ATTEMPT_ID BETWEEN 9110 AND 9116 AND DISPLAY_ORDER = 5;
UPDATE EXAM_ATTEMPT_QUESTION SET SOURCE_QUESTION_ID = 9251 WHERE ATTEMPT_ID BETWEEN 9110 AND 9116 AND DISPLAY_ORDER = 6;

UPDATE EXAM_ATTEMPT_ANSWER SET TEXT_ANSWER = 'Abstraction hides the implementation details and shows only the essential features, for example an interface that declares what a service does without saying how it does it.' WHERE ATTEMPT_ID = 9110 AND QUESTION_ID IN (SELECT ID FROM EXAM_ATTEMPT_QUESTION WHERE ATTEMPT_ID = 9110 AND DISPLAY_ORDER = 5);
UPDATE EXAM_ATTEMPT_ANSWER SET TEXT_ANSWER = 'Encapsulation means bundling the data and the methods that operate on that data into a single class and restricting direct access to some of the components. This protects the internal state of an object and makes the code easier to maintain and change.' WHERE ATTEMPT_ID = 9111 AND QUESTION_ID IN (SELECT ID FROM EXAM_ATTEMPT_QUESTION WHERE ATTEMPT_ID = 9111 AND DISPLAY_ORDER = 5);
UPDATE EXAM_ATTEMPT_ANSWER SET TEXT_ANSWER = 'Encapsulation means bundling the data and the methods that operate on that data into a single class and restricting direct access to some of the components. This protects the internal state of an object and makes the code easier to maintain and change.' WHERE ATTEMPT_ID = 9112 AND QUESTION_ID IN (SELECT ID FROM EXAM_ATTEMPT_QUESTION WHERE ATTEMPT_ID = 9112 AND DISPLAY_ORDER = 5);
UPDATE EXAM_ATTEMPT_ANSWER SET TEXT_ANSWER = 'Encapsulation means bundling the data and the methods that work on that data into one class and restricting direct access to some of its components. This protects the internal state of an object and makes code easier to maintain and modify.' WHERE ATTEMPT_ID = 9114 AND QUESTION_ID IN (SELECT ID FROM EXAM_ATTEMPT_QUESTION WHERE ATTEMPT_ID = 9114 AND DISPLAY_ORDER = 5);
UPDATE EXAM_ATTEMPT_ANSWER SET TEXT_ANSWER = 'A constructor initialises a new object and has the same name as the class. It has no return type and can be overloaded with different parameter lists.' WHERE ATTEMPT_ID = 9113 AND QUESTION_ID IN (SELECT ID FROM EXAM_ATTEMPT_QUESTION WHERE ATTEMPT_ID = 9113 AND DISPLAY_ORDER = 5);
UPDATE EXAM_ATTEMPT_ANSWER SET TEXT_ANSWER = 'Inheritance lets a class reuse the fields and methods of a parent class using the extends keyword, which reduces duplicated code and models is-a relationships.' WHERE ATTEMPT_ID = 9115 AND QUESTION_ID IN (SELECT ID FROM EXAM_ATTEMPT_QUESTION WHERE ATTEMPT_ID = 9115 AND DISPLAY_ORDER = 5);
UPDATE EXAM_ATTEMPT_ANSWER SET TEXT_ANSWER = 'Polymorphism allows one interface to be used for many different implementations. At runtime the JVM chooses the overridden method of the actual object type, so the same call can behave differently for each subclass.' WHERE ATTEMPT_ID = 9110 AND QUESTION_ID IN (SELECT ID FROM EXAM_ATTEMPT_QUESTION WHERE ATTEMPT_ID = 9110 AND DISPLAY_ORDER = 6);
UPDATE EXAM_ATTEMPT_ANSWER SET TEXT_ANSWER = 'Polymorphism allows one interface to be used for many different implementations. At runtime the JVM chooses the overridden method of the actual object type, so the same call can behave differently for each subclass.' WHERE ATTEMPT_ID = 9115 AND QUESTION_ID IN (SELECT ID FROM EXAM_ATTEMPT_QUESTION WHERE ATTEMPT_ID = 9115 AND DISPLAY_ORDER = 6);
UPDATE EXAM_ATTEMPT_ANSWER SET TEXT_ANSWER = 'An abstract class can hold state and partial implementations while an interface only declares behaviour; a class may implement many interfaces but extend one class.' WHERE ATTEMPT_ID = 9111 AND QUESTION_ID IN (SELECT ID FROM EXAM_ATTEMPT_QUESTION WHERE ATTEMPT_ID = 9111 AND DISPLAY_ORDER = 6);
UPDATE EXAM_ATTEMPT_ANSWER SET TEXT_ANSWER = 'The static keyword binds a member to the class itself instead of to an instance, so all objects share one copy of it.' WHERE ATTEMPT_ID = 9112 AND QUESTION_ID IN (SELECT ID FROM EXAM_ATTEMPT_QUESTION WHERE ATTEMPT_ID = 9112 AND DISPLAY_ORDER = 6);
UPDATE EXAM_ATTEMPT_ANSWER SET TEXT_ANSWER = 'Exceptions signal abnormal situations; checked exceptions must be handled or declared, unchecked ones extend RuntimeException.' WHERE ATTEMPT_ID = 9113 AND QUESTION_ID IN (SELECT ID FROM EXAM_ATTEMPT_QUESTION WHERE ATTEMPT_ID = 9113 AND DISPLAY_ORDER = 6);
UPDATE EXAM_ATTEMPT_ANSWER SET TEXT_ANSWER = 'Garbage collection automatically frees memory of objects that are no longer reachable from any live thread.' WHERE ATTEMPT_ID = 9114 AND QUESTION_ID IN (SELECT ID FROM EXAM_ATTEMPT_QUESTION WHERE ATTEMPT_ID = 9114 AND DISPLAY_ORDER = 6);

-- Submitted too fast (< 20% of the exam time): shorten the attempts
UPDATE EXAM_ATTEMPT SET SUBMITTED_AT = DATEADD('MINUTE', 6, STARTED_AT) WHERE ID = 9113;  -- 6 of 45 min
UPDATE EXAM_ATTEMPT SET SUBMITTED_AT = DATEADD('MINUTE', 2, STARTED_AT) WHERE ID = 9109;  -- 2 of 15 min

